function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);render();const min=Math.floor(matchTime),sec=Math.floor((matchTime-min)*60);document.getElementById('clock').textContent=String(min).padStart(2,'0')+':'+String(sec).padStart(2,'0');requestAnimationFrame(frame)}
let shotStart=0,stickPointer=null;
function chargeStart(){shotStart=performance.now();shootCharge=0}
function chargeEnd(){if(!shotStart)return;shootCharge=clamp((performance.now()-shotStart)/1100,0,1);shotStart=0;shoot()}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Enter'){start();return}if(e.code==='Escape'||e.code==='KeyP'){pause();return}if(e.code==='KeyQ'){switchPlayer();return}if(e.code==='Space'){pass();return}if(e.code==='KeyX')chargeStart()});
addEventListener('keyup',e=>{keys.delete(e.code);if(e.code==='KeyX')chargeEnd()});
addEventListener('blur',()=>{keys.clear();input.x=input.y=0;if(shotStart)chargeEnd()});
document.getElementById('play').addEventListener('click',()=>{if(!playing)resetMatch();else start()});
document.getElementById('pause').addEventListener('click',pause);
document.getElementById('how').addEventListener('click',()=>{const t=document.getElementById('promptText');t.innerHTML='Move: WASD / arrows &nbsp; · &nbsp; Sprint: Shift<br>Pass / tackle: Space &nbsp; · &nbsp; Shoot: hold X<br>Switch player: Q &nbsp; · &nbsp; Pause: Esc';document.getElementById('promptTitle').innerHTML='Play your<br>way.';document.getElementById('how').style.display='none'});
document.getElementById('sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♫':'♩';e.currentTarget.style.color=soundOn?'#d8ff57':''});
const stick=document.getElementById('stick'),knob=document.getElementById('knob');
stick.addEventListener('pointerdown',e=>{stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});
stick.addEventListener('pointermove',e=>{if(e.pointerId===stickPointer)moveStick(e)});
